package dev.raf.radar;
import org.junit.*;import org.junit.rules.TemporaryFolder;import static org.junit.Assert.*;import java.io.*;import org.json.*;
public class PointHistoryCacheTest {
 @Rule public TemporaryFolder temp=new TemporaryFolder();
 JSONObject fixture(String date)throws Exception{JSONArray slots=new JSONArray();for(int h=0;h<24;h++){JSONArray bins=new JSONArray();for(int i=0;i<12;i++)bins.put(new JSONObject().put("count",0).put("value",JSONObject.NULL));slots.put(new JSONObject().put("hour",h).put("bins",bins));}return new JSONObject().put("schema",2).put("date",date).put("timezone","UTC").put("slots",slots);}
 @Test public void cacheSurvivesRestartAndSeparatesOwnerDateLocationAndTimezone()throws Exception{File root=temp.newFolder();Point p=new Point("one","Name",55,61,false);PointHistoryCache c=new PointHistoryCache(root);c.save(1,p,"2026-10-29","UTC",fixture("2026-10-29"));PointHistoryCache reopened=new PointHistoryCache(root);assertNotNull(reopened.read(1,p,"2026-10-29","UTC"));assertNull(reopened.read(2,p,"2026-10-29","UTC"));assertNull(reopened.read(1,p,"2026-10-28","UTC"));assertNull(reopened.read(1,p,"2026-10-29","Asia/Yekaterinburg"));p.name="Renamed";assertNotNull(reopened.read(1,p,"2026-10-29","UTC"));p.lat=56;assertNull(reopened.read(1,p,"2026-10-29","UTC"));}
 @Test public void malformedOrWrongDayDoesNotBecomeValidSavedHistory()throws Exception{File root=temp.newFolder();Point p=new Point("one","Name",55,61,false);PointHistoryCache c=new PointHistoryCache(root);c.save(1,p,"2026-10-29","UTC",fixture("2026-10-28"));assertNull(c.read(1,p,"2026-10-29","UTC"));DiagnosticJournal.write(new File(root,c.key(1,p,"2026-10-29","UTC")+".json"),"broken");assertNull(c.read(1,p,"2026-10-29","UTC"));assertFalse(PointHistoryCache.valid(new JSONObject(),"2026-10-29","UTC"));}
}
